const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const fuente = (body.fuente || '').trim();
  const validFuentes = ['BIMobject','ACAE','BEDEC','PDF','Newsletter','Manual'];
  if (!validFuentes.includes(fuente)) {
    return [{ json: { _error: 'INVALID_FUENTE', _status: 400, _details: 'fuente debe ser uno de: ' + validFuentes.join(', ') } }];
  }
  const items = Array.isArray(body.items) ? body.items : [];
  if (items.length === 0) {
    return [{ json: { _error: 'NO_ITEMS', _status: 400, _details: 'body.items debe ser array no vacio' } }];
  }
  if (items.length > 200) {
    return [{ json: { _error: 'TOO_MANY_ITEMS', _status: 413, _details: 'max 200 items por sync (recibidos ' + items.length + '). Trocea en lotes.' } }];
  }
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    fuente,
    items,
    items_count: items.length,
    request_id: 'sync_' + Math.random().toString(36).slice(2, 10),
    started_at_ms: Date.now()
  }}];
} catch (e) { return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }]; }

const sess = $('Decode JWT + Validate').first().json;
const items = sess.items;
const validCategorias = ['ceramica','sanitarios','griferia','carpinteria_interior','carpinteria_exterior','aislamiento','impermeabilizacion','pintura','pavimento','revestimiento','iluminacion','electrodomesticos','climatizacion','fontaneria','electricidad','otros'];
const validUnidades = ['m2','m3','ml','ud','kg','l'];

// Normalizar + validar cada item. Generar texto de embedding (nombre+marca+desc).
const normalized = [];
const errors = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i] || {};
  const e = [];
  if (!it.nombre || typeof it.nombre !== 'string') e.push('nombre requerido');
  if (!it.marca || typeof it.marca !== 'string') e.push('marca requerido');
  if (!it.categoria || !validCategorias.includes(it.categoria)) e.push('categoria invalida (' + (it.categoria||'?') + ')');
  if (it.unidad && !validUnidades.includes(it.unidad)) e.push('unidad invalida (' + it.unidad + ')');
  if (e.length) { errors.push({ idx: i, sku: it.sku_fabricante || null, errors: e }); continue; }
  const embedText = [it.nombre, it.marca, it.categoria, it.descripcion || ''].filter(Boolean).join(' | ').slice(0, 500);
  normalized.push({
    sku_fabricante: it.sku_fabricante || null,
    nombre: it.nombre.slice(0, 300),
    marca: it.marca.slice(0, 100),
    categoria: it.categoria,
    precio_pvp_eur: typeof it.precio === 'number' ? it.precio : (typeof it.precio_pvp_eur === 'number' ? it.precio_pvp_eur : null),
    unidad: it.unidad || null,
    fecha_precio: it.fecha_precio || new Date().toISOString(),
    url_fabricante: it.url_fabricante || null,
    url_bimobject: it.url_bimobject || null,
    epd_url: it.epd_url || null,
    huella_co2_kg: typeof it.huella_co2_kg === 'number' ? it.huella_co2_kg : null,
    descripcion: it.descripcion || null,
    raw_metadata: it.raw_metadata || {},
    embed_text: embedText
  });
}
return [{ json: {
  ...sess,
  sync_log_id: $input.first().json.id,
  normalized,
  normalized_count: normalized.length,
  validation_errors: errors,
  embed_inputs: normalized.map(n => n.embed_text)
}}];

const emb = $input.first()?.json;
const built = $('Normalize + Validate Items').first().json;
if (!emb?.data || !Array.isArray(emb.data)) {
  return [{ json: { _error: 'EMBEDDINGS_FAILED', _status: 502, _details: 'OpenAI no devolvio data[]', sync_log_id: built.sync_log_id, started_at_ms: built.started_at_ms } }];
}
if (emb.data.length !== built.normalized.length) {
  return [{ json: { _error: 'EMBEDDINGS_COUNT_MISMATCH', _status: 502, _details: 'esperados ' + built.normalized.length + ' vectores, recibidos ' + emb.data.length, sync_log_id: built.sync_log_id, started_at_ms: built.started_at_ms } }];
}
// Adjuntar embedding a cada item normalizado
const withEmb = built.normalized.map((n, i) => ({
  ...n,
  embedding: emb.data[i].embedding
}));
return [{ json: {
  ...built,
  with_embedding: withEmb,
  embedding_tokens: emb.usage?.total_tokens || 0,
  embedding_model: emb.model || 'text-embedding-3-small'
}}];

